static bool boost_points_close(const BoostPoint& a, const BoostPoint& b) {
    return std::abs(a.x() - b.x()) <= TOL && std::abs(a.y() - b.y()) <= TOL;
}

static double boost_cross(const BoostPoint& a, const BoostPoint& b, const BoostPoint& c) {
    const double abx = b.x() - a.x();
    const double aby = b.y() - a.y();
    const double bcx = c.x() - b.x();
    const double bcy = c.y() - b.y();
    return abx * bcy - aby * bcx;
}

static Polygon cgal_polygon_from_boost_outer(const BoostPolygon& polygon) {
    Polygon result;
    const auto& outer = polygon.outer();
    if (outer.size() < 4) {
        return result;
    }

    std::vector<BoostPoint> sanitized;
    sanitized.reserve(outer.size() - 1);
    for (std::size_t i = 0; i + 1 < outer.size(); ++i) {
        if (!sanitized.empty() && boost_points_close(sanitized.back(), outer[i])) {
            continue;
        }
        sanitized.push_back(outer[i]);
    }

    if (sanitized.size() >= 2 && boost_points_close(sanitized.front(), sanitized.back())) {
        sanitized.pop_back();
    }

    bool changed = true;
    while (changed && sanitized.size() >= 3) {
        changed = false;
        for (std::size_t i = 0; i < sanitized.size(); ++i) {
            const std::size_t prev = (i + sanitized.size() - 1) % sanitized.size();
            const std::size_t next = (i + 1) % sanitized.size();
            const double cross = boost_cross(sanitized[prev], sanitized[i], sanitized[next]);
            if (std::abs(cross) <= TOL) {
                sanitized.erase(sanitized.begin() + static_cast<std::ptrdiff_t>(i));
                changed = true;
                break;
            }
        }
    }

    if (sanitized.size() < 3) {
        return result;
    }

    for (const auto& point : sanitized) {
        result.push_back(Point(point.x(), point.y()));
    }

    if (result.size() >= 3 && result.is_clockwise_oriented()) {
        result.reverse_orientation();
    }
    return result;
}

