#include "drawing.h"
#include <QApplication>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <optional>
#include <string>
#include <vector>
#include <cmath>

extern const double BMIN = -10000.0;
extern const double BMAX =  10000.0;

using P = Point;

struct CompareStats {
    std::size_t count_a = 0;
    std::size_t count_b = 0;
    std::size_t overlap = 0;
    double max_point_distance = 0.0;
    double mean_point_distance = 0.0;
    double bbox_diag_a = 0.0;
    double bbox_diag_b = 0.0;
};

static bool parse_n_pairs(const std::filesystem::path& path, std::vector<P>& out) {
    std::ifstream in(path);
    if (!in) return false;
    std::size_t count = 0;
    if (!(in >> count)) return false;
    out.clear();
    out.reserve(count);
    for (std::size_t i = 0; i < count; ++i) {
        double x = 0.0;
        double y = 0.0;
        if (!(in >> x >> y)) return false;
        out.emplace_back(x, y);
    }
    return true;
}

static std::filesystem::path resolve_repo_root(char** argv) {
    auto looks_like_repo_root = [](const std::filesystem::path& dir) {
        return std::filesystem::exists(dir / "CMakeLists.txt")
            && std::filesystem::exists(dir / "data");
    };

    auto climb = [&](std::filesystem::path start) {
        std::error_code ec;
        start = std::filesystem::weakly_canonical(start, ec);
        if (ec) start = start.lexically_normal();
        auto dir = std::filesystem::is_regular_file(start, ec) ? start.parent_path() : start;
        while (!dir.empty()) {
            if (looks_like_repo_root(dir)) return dir;
            auto parent = dir.parent_path();
            if (parent == dir) break;
            dir = parent;
        }
        return std::filesystem::path{};
    };

    if (auto root = climb(argv[0]); !root.empty()) return root;
    if (auto root = climb(std::filesystem::current_path()); !root.empty()) return root;
    return std::filesystem::current_path();
}

static double point_distance(const P& a, const P& b) {
    const double dx = CGAL::to_double(a.x()) - CGAL::to_double(b.x());
    const double dy = CGAL::to_double(a.y()) - CGAL::to_double(b.y());
    return std::hypot(dx, dy);
}

static double bbox_diag(const std::vector<P>& pts) {
    if (pts.empty()) return 0.0;
    double min_x = std::numeric_limits<double>::infinity();
    double min_y = std::numeric_limits<double>::infinity();
    double max_x = -std::numeric_limits<double>::infinity();
    double max_y = -std::numeric_limits<double>::infinity();
    for (const auto& point : pts) {
        const double x = CGAL::to_double(point.x());
        const double y = CGAL::to_double(point.y());
        min_x = std::min(min_x, x);
        min_y = std::min(min_y, y);
        max_x = std::max(max_x, x);
        max_y = std::max(max_y, y);
    }
    return std::hypot(max_x - min_x, max_y - min_y);
}

static CompareStats compare_curves(const std::vector<P>& a, const std::vector<P>& b) {
    CompareStats stats;
    stats.count_a = a.size();
    stats.count_b = b.size();
    stats.overlap = std::min(a.size(), b.size());
    stats.bbox_diag_a = bbox_diag(a);
    stats.bbox_diag_b = bbox_diag(b);
    if (stats.overlap == 0) {
        return stats;
    }

    double total = 0.0;
    for (std::size_t i = 0; i < stats.overlap; ++i) {
        const double dist = point_distance(a[i], b[i]);
        stats.max_point_distance = std::max(stats.max_point_distance, dist);
        total += dist;
    }
    stats.mean_point_distance = total / static_cast<double>(stats.overlap);
    return stats;
}

static void print_stats(const std::filesystem::path& a_path,
                        const std::filesystem::path& b_path,
                        const CompareStats& stats) {
    std::cout << std::fixed << std::setprecision(6);
    std::cout << "Compare A: " << a_path << '\n';
    std::cout << "Compare B: " << b_path << '\n';
    std::cout << "points_a=" << stats.count_a << "\n";
    std::cout << "points_b=" << stats.count_b << "\n";
    std::cout << "count_delta="
              << static_cast<long long>(stats.count_a) - static_cast<long long>(stats.count_b)
              << "\n";
    std::cout << "paired_points=" << stats.overlap << "\n";
    std::cout << "mean_paired_distance=" << stats.mean_point_distance << "\n";
    std::cout << "max_paired_distance=" << stats.max_point_distance << "\n";
    std::cout << "bbox_diag_a=" << stats.bbox_diag_a << "\n";
    std::cout << "bbox_diag_b=" << stats.bbox_diag_b << "\n";

    const double scale = std::max(stats.bbox_diag_a, stats.bbox_diag_b);
    if (scale > 0.0) {
        std::cout << "max_distance_over_bbox=" << (stats.max_point_distance / scale) << "\n";
        std::cout << "mean_distance_over_bbox=" << (stats.mean_point_distance / scale) << "\n";
    }
}

static void print_help(const char* argv0) {
    std::cout << "Usage:\n"
              << "  " << argv0 << " --a <file> --b <file> [--no-gui]\n"
              << "  " << argv0 << " --id <n> [--a-name <file>] [--b-name <file>] [--no-gui]\n\n"
              << "Defaults for --id mode resolve under data/taxi_simplified/<id>/ with\n"
              << "  A = our_simplified.txt\n"
              << "  B = 0.500000_100.000000_our_simplified.txt\n";
}

int main(int argc, char** argv) {
    std::optional<int> case_id;
    std::string a_name = "our_simplified.txt";
    std::string b_name = "0.500000_100.000000_our_simplified.txt";
    std::filesystem::path a_path;
    std::filesystem::path b_path;
    bool show_gui = true;

    for (int i = 1; i < argc; ++i) {
        const std::string arg = argv[i];
        if (arg == "-h" || arg == "--help") {
            print_help(argv[0]);
            return 0;
        }
        if (arg == "--id" && i + 1 < argc) {
            case_id = std::stoi(argv[++i]);
        } else if (arg == "--a" && i + 1 < argc) {
            a_path = argv[++i];
        } else if (arg == "--b" && i + 1 < argc) {
            b_path = argv[++i];
        } else if (arg == "--a-name" && i + 1 < argc) {
            a_name = argv[++i];
        } else if (arg == "--b-name" && i + 1 < argc) {
            b_name = argv[++i];
        } else if (arg == "--no-gui") {
            show_gui = false;
        } else {
            std::cerr << "Unknown or incomplete argument: " << arg << "\n";
            print_help(argv[0]);
            return 1;
        }
    }

    if (case_id.has_value()) {
        const auto repo_root = resolve_repo_root(argv);
        const auto dir = repo_root / "data" / "taxi_simplified" / std::to_string(*case_id);
        if (a_path.empty()) a_path = dir / a_name;
        if (b_path.empty()) b_path = dir / b_name;
    }

    if (a_path.empty() || b_path.empty()) {
        print_help(argv[0]);
        return 1;
    }

    std::vector<P> curve_a;
    std::vector<P> curve_b;
    if (!parse_n_pairs(a_path, curve_a)) {
        std::cerr << "Failed to read " << a_path << "\n";
        return 1;
    }
    if (!parse_n_pairs(b_path, curve_b)) {
        std::cerr << "Failed to read " << b_path << "\n";
        return 1;
    }

    const CompareStats stats = compare_curves(curve_a, curve_b);
    print_stats(a_path, b_path, stats);

    if (!show_gui) {
        return 0;
    }

    QApplication app(argc, argv);
    MultiViewer viewer;
    viewer.setWindowTitle("Compare simplified trajectories");
    viewer.addCurve(curve_a, QColor(220, 20, 60), QString::fromStdString(a_path.filename().string()));
    viewer.addCurve(curve_b, QColor(30, 144, 255), QString::fromStdString(b_path.filename().string()));
    viewer.resize(1000, 800);
    viewer.show();
    return app.exec();
}

