static bool point_less_lexicographically(const Point& lhs, const Point& rhs) {
    const double lhs_x = CGAL::to_double(lhs.x());
    const double lhs_y = CGAL::to_double(lhs.y());
    const double rhs_x = CGAL::to_double(rhs.x());
    const double rhs_y = CGAL::to_double(rhs.y());
    if (std::abs(lhs_x - rhs_x) > TOL) {
        return lhs_x < rhs_x;
    }
    return lhs_y < rhs_y - TOL;
}

static void canonicalize_polygon_start(Polygon& polygon) {
    if (polygon.size() < 2) {
        return;
    }

    std::size_t best_index = 0;
    for (std::size_t i = 1; i < polygon.size(); ++i) {
        if (point_less_lexicographically(polygon[i], polygon[best_index])) {
            best_index = i;
        }
    }

    if (best_index == 0) {
        return;
    }

    Polygon rotated;
    for (std::size_t offset = 0; offset < polygon.size(); ++offset) {
        rotated.push_back(polygon[(best_index + offset) % polygon.size()]);
    }
    polygon = std::move(rotated);
}

