import re

def find_segment(trace_path, start, cur, idx):
    results = []
    with open(trace_path) as f:
        for line in f:
            m = re.match(r'(SEGMENT|S |F |G |INTERSECTION|STEP_NEW_S|STEP_S_NEXT) ', line)
            if m:
                tag = m.group(1)
                if tag == 'SEGMENT':
                    sm = re.match(r'SEGMENT start=(\d+) cur=(\d+) idx=(\d+)', line)
                    if sm:
                        s, c, i = int(sm.group(1)), int(sm.group(2)), int(sm.group(3))
                        if s == start and c == cur and i == idx:
                            results.append(('SEG', line.rstrip()))
                elif tag == 'S ':
                    sm = re.match(r'S start=(\d+) cur=(\d+) idx=(\d+)', line)
                    if sm:
                        s, c, i = int(sm.group(1)), int(sm.group(2)), int(sm.group(3))
                        if s == start and c == cur and i == idx:
                            results.append(('S', line.rstrip()))
                elif tag == 'F ':
                    sm = re.match(r'F start=(\d+) cur=(\d+) idx=(\d+)', line)
                    if sm:
                        s, c, i = int(sm.group(1)), int(sm.group(2)), int(sm.group(3))
                        if s == start and c == cur and i == idx:
                            results.append(('F', line.rstrip()))
                elif tag == 'G ':
                    sm = re.match(r'G start=(\d+) cur=(\d+) idx=(\d+)', line)
                    if sm:
                        s, c, i = int(sm.group(1)), int(sm.group(2)), int(sm.group(3))
                        if s == start and c == cur and i == idx:
                            results.append(('G', line.rstrip()))
                elif tag == 'INTERSECTION':
                    sm = re.match(r'INTERSECTION start=(\d+) cur=(\d+) idx=(\d+)', line)
                    if sm:
                        s, c, i = int(sm.group(1)), int(sm.group(2)), int(sm.group(3))
                        if s == start and c == cur and i == idx:
                            results.append(('ISEC', line.rstrip()))
                elif tag == 'STEP_NEW_S':
                    sm = re.match(r'STEP_NEW_S start=(\d+) cur=(\d+) idx=(\d+)', line)
                    if sm:
                        s, c, i = int(sm.group(1)), int(sm.group(2)), int(sm.group(3))
                        if s == start and c == cur and i == idx:
                            results.append(('STEP', line.rstrip()))
                elif tag == 'STEP_S_NEXT':
                    sm = re.match(r'STEP_S_NEXT start=(\d+) cur=(\d+) idx=(\d+)', line)
                    if sm:
                        s, c, i = int(sm.group(1)), int(sm.group(2)), int(sm.group(3))
                        if s == start and c == cur and i == idx:
                            results.append(('SNEXT', line.rstrip()))
    return results

