#include <CGAL/Exact_predicates_exact_constructions_kernel.h>
#include <CGAL/Polygon_2.h>
#include <CGAL/convex_hull_2.h>
#include <boost/geometry.hpp>
#include <boost/geometry/geometries/point_xy.hpp>
#include <boost/geometry/geometries/polygon.hpp>
#include <iostream>
#include <vector>
#include <sstream>
#include <iomanip>
#include <cmath>

using Kernel = CGAL::Exact_predicates_exact_constructions_kernel;
using Point = Kernel::Point_2;
using Polygon = CGAL::Polygon_2<Kernel>;
using Polygon_with_holes = CGAL::Polygon_with_holes_2<Kernel>;
using BoostCoord = double;
using BoostPoint = boost::geometry::model::d2::point_xy<BoostCoord>;
using BoostPolygon = boost::geometry::model::polygon<BoostPoint>;

constexpr double TOL = 1e-6;
constexpr double SQRT2 = 1.41421356237;
constexpr double BMIN = -10000;
constexpr double BMAX = 10000;
double DELTA = 200;
double EPSILON = 0.5;
double GRID_val() { return EPSILON * DELTA / (2 * SQRT2); }
double R_val() { return (1.0 + EPSILON / 2.0) * DELTA; }

std::vector<Point> parse_polygon(const std::string& s) {
    std::vector<Point> pts;
    size_t start = s.find('[');
    size_t end = s.find(']');
    if (start == std::string::npos || end == std::string::npos) return pts;
    std::string inner = s.substr(start + 1, end - start - 1);
    std::istringstream iss(inner);
    std::string token;
    while (std::getline(iss, token, ';')) {
        if (token.empty()) continue;
        if (token.front() == '(') token = token.substr(1);
        if (token.back() == ')') token.pop_back();
        size_t comma = token.find(',');
        if (comma == std::string::npos) continue;
        double x = std::stod(token.substr(0, comma));
        double y = std::stod(token.substr(comma + 1));
        pts.emplace_back(x, y);
    }
    return pts;
}

std::string fmt_pts(const std::vector<Point>& pts) {
    std::ostringstream oss;
    for (size_t i = 0; i < pts.size(); ++i) {
        if (i) oss << ';';
        oss << std::setprecision(15) << CGAL::to_double(pts[i].x())
            << ',' << CGAL::to_double(pts[i].y());
    }
    return oss.str();
}

// This is EXACTLY how simplify.cpp creates the Boost polygon
BoostPolygon to_boost_polygon(const Polygon& polygon) {
    BoostPolygon boost_polygon;
    auto& outer = boost_polygon.outer();
    for (auto vertex = polygon.vertices_begin(); vertex != polygon.vertices_end(); ++vertex) {
        outer.emplace_back(CGAL::to_double(vertex->x()), CGAL::to_double(vertex->y()));
    }
    if (!outer.empty()) {
        const auto& first = outer.front();
        const auto& last = outer.back();
        if (first.x() != last.x() || first.y() != last.y()) {
            outer.push_back(first);
        }
    }
    boost::geometry::correct(boost_polygon);
    return boost_polygon;
}

bool boost_points_close(const BoostPoint& a, const BoostPoint& b) {
    return std::abs(a.x() - b.x()) <= TOL && std::abs(a.y() - b.y()) <= TOL;
}

static double boost_cross(const BoostPoint& a, const BoostPoint& b, const BoostPoint& c) {
    const double abx = b.x() - a.x();
    const double aby = b.y() - a.y();
    const double bcx = c.x() - b.x();
    const double bcy = c.y() - b.y();
    return abx * bcy - aby * bcx;
}

// This is EXACTLY how simplify.cpp converts back from Boost
Polygon cgal_polygon_from_boost_outer(const BoostPolygon& polygon) {
    Polygon result;
    const auto& outer = polygon.outer();
    if (outer.size() < 4) {
        std::cerr << "  WARNING: outer.size() = " << outer.size() << " < 4, returning empty\n";
        return result;
    }

    std::vector<BoostPoint> sanitized;
    sanitized.reserve(outer.size());
    for (const auto& pt : outer) {
        if (!sanitized.empty() && boost_points_close(sanitized.back(), pt)) {
            continue;
        }
        sanitized.push_back(pt);
    }

    if (sanitized.size() >= 2 && boost_points_close(sanitized.front(), sanitized.back())) {
        sanitized.pop_back();
    }

    if (sanitized.size() < 3) {
        std::cerr << "  WARNING: sanitized.size() = " << sanitized.size() << " < 3, returning empty\n";
        return result;
    }

    for (const auto& point : sanitized) {
        result.push_back(Point(static_cast<double>(point.x()), static_cast<double>(point.y())));
    }

    if (result.size() >= 3 && result.is_clockwise_oriented()) {
        result.reverse_orientation();
    }
    // NO canonicalize_polygon_start

    return result;
}

std::vector<Polygon_with_holes> intersect_polygons_boost(const Polygon& lhs, const Polygon& rhs) {
    std::vector<BoostPolygon> boost_output;
    boost::geometry::intersection(to_boost_polygon(lhs), to_boost_polygon(rhs), boost_output);

    std::vector<Polygon_with_holes> result;
    result.reserve(boost_output.size());
    for (const auto& boost_polygon : boost_output) {
        Polygon outer = cgal_polygon_from_boost_outer(boost_polygon);
        if (outer.size() < 3) {
            continue;
        }
        result.emplace_back(std::move(outer));
    }
    return result;
}

