#!/bin/bash
# Compare adapted vs original SQUISH on a small input where the difference
# between min-SED and max-SED removal is observable.
set -e
cd /Users/sinchunyeung/Simplification-of-Trajectory-Streams

# Build a synthetic 2D trajectory: a clear zigzag with one big "outlier" point
# (high SED) and several "smooth" points (low SED).
# Under correct SQUISH (min-SED removal): the smooth points should be dropped first.
# Under the buggy adapted code (max-SED removal): the outlier is dropped first.

cat > /tmp/test_squish.txt <<'EOF'
10
0 0
1 0.05
2 0.1
3 5
4 0.15
5 0.2
6 0.25
7 0.3
8 0.35
9 0.4
EOF

# Run adapted with ratio 0.5 (buffer size 5)
./traj-compression/online/SQUISH/SQUISH_adapted /tmp/test_squish.txt 0.5 /tmp/test_squish_out_adapted.txt
echo "--- adapted output ---"
cat /tmp/test_squish_out_adapted.txt

# Now build a stripped version of original SQUISH that handles 2D input (x y)
# instead of 3D (lat lon time). We just clone SQUISH.cpp and patch the struct
# and the SED projection to use x,y only with pseudo-time = index.
cat > /tmp/squish_patched.cpp <<'EOF'
#include<iostream>
#include<vector>
#include<fstream>
#include<string>
#include<sstream>
#include<math.h>
#include<algorithm>
using namespace std;
typedef struct Point{ int index; double x, y, time; }Point;
typedef struct { Point point; double sed; } GPSPointWithSED;
vector<Point> points;
void gpsreader(string filename){
    ifstream fin(filename.c_str());
    if (!fin){ cout<<"open error\n"; exit(0); }
    int n; fin>>n;
    int idx=0; double x,y;
    while (fin>>x>>y && idx<n){
        Point p; p.x=x; p.y=y; p.time=idx; p.index=idx; idx++;
        points.push_back(p);
    }
}
double cacl_SED(Point s, Point m, Point e){
    double numerator = m.time - s.time;
    double denominator = e.time - s.time;
    double time_ratio = denominator == 0 ? 1 : numerator / denominator;
    double x = s.x + (e.x - s.x)*time_ratio;
    double y = s.y + (e.y - s.y)*time_ratio;
    double xd = x - m.x, yd = y - m.y;
    return sqrt(xd*xd + yd*yd);
}
vector<GPSPointWithSED> SQUISH(double cmp_ratio){
    int max_buffer_size = (int)(cmp_ratio * points.size());
    vector<GPSPointWithSED> buffer;
    buffer.reserve(max_buffer_size + 1);
    buffer.push_back({ points[0], 0 });
    if (max_buffer_size > 2) {
        buffer.push_back({ points[1], 0 });
        for (int i = 2; i < points.size(); ++i){
            buffer.push_back({ points[i], 0 });
            Point segment_start = buffer[buffer.size() - 3].point;
            Point segment_end = buffer[buffer.size() - 1].point;
            buffer[buffer.size() - 2].sed += cacl_SED(segment_start, buffer[buffer.size() - 2].point, segment_end);
            if (buffer.size() > max_buffer_size){
                auto start = buffer.begin();
                ++start;
                auto to_remove = buffer.end();
                for (auto it = buffer.begin() + 1; it != buffer.end() - 1; ++it) {
                    if (to_remove == buffer.end() || it->sed < to_remove->sed) {
                        to_remove = it;
                    }
                }
                (to_remove - 1)->sed += to_remove->sed;
                (to_remove + 1)->sed += to_remove->sed;
                buffer.erase(to_remove);
            }
        }
    } else {
        buffer.push_back({ points[points.size() - 1], 0 });
    }
    return buffer;
}
int main(int argc, char** args){
    gpsreader(args[1]);
    double ratio = atof(args[2]);
    vector<GPSPointWithSED> out = SQUISH(ratio);
    cout << out.size() << "\n";
    cout.setf(ios::fixed); cout.precision(6);
    for (size_t i=0;i<out.size();i++) cout<<out[i].point.x<<" "<<out[i].point.y<<"\n";
}
